-- Tier weapons and the raid augment vendor (gen_tier_gear.py with tier_gear.json; only the new rows, so the
-- rest of the live tier gear is untouched). 30 Legendary Plane of Time weapons and shields and 2 stats-only range
-- items copied to gear tiers 1-5 (x1.0-3.0), one copy per class that can use it, each also rolling that class's
-- affixes; sold by a Weaponsmith per tier at a deepest clear of 75/175/275/375/475. The Legendary Prismatic Scales
-- and Splinters of Time copied to raid tiers 1-4 (x1.5-3.0), sold for Chronal Prisms by the Prism_Augmenter beside
-- the Raid Portal, each tier unlocked by the raid_cleared bucket. Items load at server start, so restart after
-- applying; shut thevoida down first or its saved state hides the new vendors.

START TRANSACTION;

DELETE FROM merchantlist WHERE merchantid BETWEEN 1200044 AND 1200048 OR merchantid = 1200072;
DELETE FROM spawn2 WHERE spawngroupID IN (SELECT spawngroupID FROM spawnentry WHERE npcID BETWEEN 1200044 AND 1200048 OR npcID = 1200072);
DELETE FROM spawnentry WHERE npcID BETWEEN 1200044 AND 1200048 OR npcID = 1200072;
DELETE FROM spawngroup WHERE name IN ('rift_tier_vendor_1200044', 'rift_tier_vendor_1200045', 'rift_tier_vendor_1200046', 'rift_tier_vendor_1200047', 'rift_tier_vendor_1200048', 'rift_tier_vendor_1200072');
DELETE FROM npc_types WHERE id BETWEEN 1200044 AND 1200048 OR id = 1200072;
DELETE FROM zone_state_spawns WHERE npc_id BETWEEN 1200044 AND 1200048 OR npc_id = 1200072;
DELETE FROM dynamic_items WHERE (item_id BETWEEN 940000 AND 964999 AND MOD(item_id, 5000) BETWEEN 2000 AND 2999) OR item_id BETWEEN 965000 AND 965499;
DELETE FROM items WHERE (id BETWEEN 940000 AND 964999 AND MOD(id, 5000) BETWEEN 2000 AND 2999) OR id BETWEEN 965000 AND 965499;

DELETE FROM zone_state_spawns WHERE npc_id = 1200072;

COMMIT;
